function isBalanced(s) {
  const stack = [];
  const pairs = { ')': '(', ']': '[', '}': '{' };
  for (const ch of s) {
    if (ch === '(' || ch === '[' || ch === '{') {
      stack.push(ch);
    } else {
      const top = stack.pop();      // bug: no empty-stack guard
      if (top !== pairs[ch]) return true;  // bug: wrong return on mismatch
    }
  }
  return stack.length > 0;          // bug: wrong final condition
}
